'use strict';
const E=HairEngine,KEY='hairflow-demo-v1';
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.version!==1)state=E.seed();}catch{state=E.seed();}
let view='overview',workspace='main',role='Руководитель',query='',stageFilter='',modal=null;
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:d}),rub=n=>fmt(n,2)+' ₽',kg=n=>fmt(n/1000,2)+' кг';
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',inventory:'<path d="m3 7 9-4 9 4-9 4-9-4Z"/><path d="M3 7v10l9 4 9-4V7M12 11v10"/>',purchases:'<path d="M7 4h10l3 5v11H4V9l3-5ZM4 9h16M9 13h6"/>',production:'<path d="M4 20V9l6 4V8l6 4V4h4v16H4ZM8 16v1m5-1v1m4-1v1"/>',sales:'<path d="M3 4h2l3 12h11l2-9H6M9 20h.01M18 20h.01"/>',partners:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',finances:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M17 11h4v5h-4a2.5 2.5 0 0 1 0-5ZM3 8V5l14-3v3"/>',graph:'<circle cx="12" cy="4" r="2"/><circle cx="5" cy="19" r="2"/><circle cx="19" cy="19" r="2"/><path d="M12 6v6M5 17v-5h14v5"/>',assistant:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',roles:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="white"/><circle cx="16" cy="12" r="2" fill="white"/><circle cx="10" cy="18" r="2" fill="white"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.inventory}</svg>`;
const labels={overview:'Обзор компании',inventory:'Волосы и остатки',purchases:'Закупки и поставки',production:'Производство',sales:'Продажи',partners:'Партнёры',finances:'Финансы',graph:'Граф происхождения',assistant:'Помощник',roles:'Роли и доступ',settings:'Настройки'};
const canFinance=()=>['Руководитель','Бухгалтер','Партнёр'].includes(role),canPurchase=()=>['Руководитель','Закупщик'].includes(role),canProcess=()=>['Руководитель','Производство','Партнёр'].includes(role),canMove=()=>['Руководитель','Склад','Партнёр'].includes(role),canSell=()=>['Руководитель','Продавец','Партнёр'].includes(role);
const wsName=()=>workspace==='main'?'Главная компания':state.partners.find(p=>p.id===workspace)?.name;
const wsTails=()=>state.tails.filter(t=>workspace==='main'||t.owner===workspace);
function available(){return wsTails().filter(t=>t.weight>0);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Браузер не разрешил сохранение. Данные останутся до закрытия страницы.');}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200);}
function btn(text,action,secondary=false){return `<button class="btn ${secondary?'secondary':''}" data-action="${action}">${text}</button>`;}
function head(title,sub,actions='',tag='Управление компанией'){return `<div class="page-head"><div><div class="eyebrow">${tag}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function metric(label,value,detail,i,featured=false){return `<div class="metric ${featured?'featured':''}"><div class="metric-top">${label}<span class="metric-icon">${icon(i)}</span></div><div class="metric-value">${value}</div><div class="metric-bottom">${detail}</div></div>`;}
function panel(title,body,sub='',actions=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${actions}</div>${body}</section>`;}
function badge(t){const color=t.stage==='Сырьё'?'orange':t.owner!=='main'?'purple':t.stage==='Продано'?'':'green';return `<span class="badge ${color}">${esc(t.stage)}</span>`;}
function lotName(t){return state.purchases.find(p=>p.id===t.lot)?.supplier||'';}
function tailsTable(tails,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Хвост / источник</th><th>Характеристики</th><th>Вес</th><th>Состояние</th><th>Где находится</th>${!compact&&canFinance()?'<th>Себестоимость</th>':''}<th></th></tr></thead><tbody>${tails.map(t=>`<tr><td><button class="tail-link" data-tail="${esc(t.id)}">${esc(t.id)}</button><small>${esc(t.lot)} · ${esc(lotName(t))}</small></td><td><strong>${t.length} см · ${esc(t.color)}</strong><small>${esc(t.quality)}${t.ombre?' · омбре':''}</small></td><td><strong>${fmt(t.weight)} г</strong><small>вход ${fmt(t.initialWeight)} г</small></td><td>${badge(t)}</td><td>${esc(t.location)}</td>${!compact&&canFinance()?`<td>${rub(t.cost)}</td>`:''}<td><button class="btn ghost" data-tail="${esc(t.id)}" aria-label="Открыть ${esc(t.id)}">${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">По выбранным условиям волос нет</td></tr>'}</tbody></table></div>`;}
function overview(){const m=E.metrics(state,workspace),all=available(),external=all.filter(t=>t.owner!=='main'),local=all.filter(t=>t.owner==='main'),latest=state.events.filter(e=>workspace==='main'||state.tails.find(t=>t.id===e.tail)?.owner===workspace).slice(-4).reverse();
 const revenueByLot=state.purchases.map(p=>({p,total:state.sales.filter(x=>x.lot===p.id&&x.owner===workspace).reduce((a,x)=>a+x.revenue,0)}));const max=Math.max(1,...revenueByLot.map(x=>x.total));
 const chart=`<div class="panel-body"><div class="chart">${revenueByLot.map(({p,total})=>`<div class="chart-col"><div class="bar-stack" style="height:${Math.max(4,total/max*140)}px"><span class="chart-value">${total?fmt(total/1000,1)+' тыс.':''}</span><div class="bar-fill" style="height:100%"></div></div><label>${esc(p.id.replace('MM-',''))}</label></div>`).join('')}</div><div class="legend"><span><i></i>Выручка по поставкам</span><span>Все операции демобазы</span></div></div>`;
 const locationGroups=['Склад сырья','Производство','Магазин'];const weights=locationGroups.map(loc=>all.filter(t=>t.location===loc).reduce((a,t)=>a+t.weight,0));const total=all.reduce((a,t)=>a+t.weight,0);const pct=total?weights[0]/total*100:0,pp=total?(weights[0]+weights[1])/total*100:0;
 const stock=`<div class="panel-body"><div class="donut-wrap"><div class="donut" style="background:conic-gradient(var(--green) 0 ${pct}%,#a8b897 ${pct}% ${pp}%,#e6ebdf ${pp}% 100%)"><div class="donut-inner">${fmt(total/1000,2)}<small>кг в наличии</small></div></div><div class="donut-legend">${locationGroups.map((loc,i)=>`<div>${loc}<b>${kg(weights[i])}</b></div>`).join('')}${workspace==='main'?`<div>У партнёров<b>${kg(external.reduce((a,t)=>a+t.weight,0))}</b></div>`:''}</div></div></div>`;
 const events=`<div class="panel-body">${latest.map(e=>`<div class="flow-line"><span class="flow-icon">${icon(e.kind==='process'?'production':e.kind==='sale'?'sales':'inventory')}</span><div><strong>${esc(e.text)}</strong><small>${esc(e.tail)} · ${new Date(e.date).toLocaleDateString('ru-RU')}</small></div></div>`).join('')}</div>`;
 return head('Всё начинается с одного среза','Закупки, движение волос и экономика — в одном пространстве.',canPurchase()?btn(icon('plus')+' Новая поставка','purchase'):'')+`<div class="metrics">${metric('Остаток своей компании',kg(m.weight),'В наличии · '+(workspace==='main'?local.length:all.length)+' учётных единиц','inventory')}${metric('Выручка',canFinance()?rub(m.revenue):'Скрыто','Включая продажи сырья партнёрам','sales')}${metric('Маржа компании',canFinance()?rub(m.margin):'Скрыто','До общих расходов · с партнёрской долей','finances',true)}${metric('Доля от партнёров',canFinance()?rub(m.shares):'Скрыто','Начислено · выплаты ещё не учтены','partners')}</div><div class="dashboard-grid">${canFinance()?panel('Выручка по поставкам',chart,'От закупки до продажи'):panel('Последние операции',events,'История движения')}${panel('Где находятся волосы',stock,'Фактические остатки')}</div>${panel('Волосы в работе',tailsTable(all.slice(0,5),true),'Нажмите на номер, чтобы открыть всю историю',`<button class="btn ghost" data-view="inventory">Все волосы ${icon('arrow')}</button>`)}<div class="dashboard-grid section-gap">${panel('Последние события',events,'Журнал действий')}${panel('Поставщики',`<div class="panel-body">${[...new Set(state.purchases.map(p=>p.supplier))].map(name=>{const ps=state.purchases.filter(p=>p.supplier===name);return `<div class="supplier-row"><div class="avatar">${esc(name.slice(0,1))}</div><div><strong>${esc(name)}</strong><span>${esc(ps[0].village)} · ${ps.length} закупки</span></div><b>${kg(ps.reduce((a,p)=>a+p.weight,0))}</b></div>`;}).join('')}</div>`,'Поступившее сырьё · демоданные')}</div>`;
}
function inventory(){const tails=available().filter(t=>(!query||[t.id,t.lot,t.color,t.location,lotName(t)].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!stageFilter||t.stage===stageFilter));return head('Каждый хвост на своём месте','Карточки, вес, характеристики и происхождение волос.',btn(icon('download')+' Выгрузить','export',true))+`<div class="toolbar"><input id="inventory-search" placeholder="Номер, поставка, цвет…" value="${esc(query)}" aria-label="Поиск волос"><select id="stage-filter" aria-label="Состояние"><option value="">Все состояния</option>${['Сырьё','Обработано','Окрашено'].map(x=>`<option ${stageFilter===x?'selected':''}>${x}</option>`).join('')}</select></div>`+panel('Волосы в наличии',tailsTable(tails),tails.length+' учётных единиц · '+kg(tails.reduce((a,t)=>a+t.weight,0)));}
function purchases(){if(workspace!=='main')return head('Поступления от главной компании','Переданные волосы автоматически доступны в вашем пространстве.')+panel('Входящие волосы',tailsTable(available()));return head('От деревни до вашего склада','Закупочная валюта, исторический курс и расходы поставки.',canPurchase()?btn(icon('plus')+' Новая поставка','purchase'):'')+panel('Поставки из Мьянмы',`<div class="table-wrap"><table><thead><tr><th>Поставка</th><th>Поставщик / деревня</th><th>Вес</th>${canPurchase()||canFinance()?'<th>Цена / кг</th><th>Курс</th><th>Стоимость с расходами</th>':''}<th></th></tr></thead><tbody>${state.purchases.map(p=>`<tr><td><strong>${esc(p.id)}</strong><small>${esc(p.date)}</small></td><td><strong>${esc(p.supplier)}</strong><small>${esc(p.village)}</small></td><td>${kg(p.weight)}</td>${canPurchase()||canFinance()?`<td>${fmt(p.price)} ${esc(p.currency)}</td><td>${fmt(p.rate,2)} ₽</td><td>${rub(p.cost)}<small>Расходы ${rub(p.expenses)}</small></td>`:''}<td><button class="btn ghost" data-tail="${esc(state.tails.find(t=>t.lot===p.id)?.id)}">Открыть</button></td></tr>`).join('')}</tbody></table></div>`,'Курс каждой закупки зафиксирован');}
function production(){const ts=available().filter(t=>workspace==='main'?t.owner==='main':t.owner===workspace),loss=ts.reduce((a,t)=>a+t.loss,0);return head('Из сырья в готовые волосы','Фиксируйте результат операции и сохраняйте историю веса.',canProcess()?btn(icon('plus')+' Обработать волосы','process'):'')+`<div class="metrics">${metric('Доступно для обработки',kg(ts.reduce((a,t)=>a+t.weight,0)),ts.length+' учётных единиц','production')}${metric('Потери по текущим карточкам',kg(loss),'Накопленные потери обработки','inventory')}${metric('Тариф обработки',rub(state.settings.tariff),'За килограмм входящего веса','settings')}${metric('Обработанные единицы',fmt(ts.filter(t=>t.processing>0).length),'Мойка, вычёс или окрас','graph')}</div>`+panel('Карточки производства',tailsTable(ts))+`<p class="note">В прототипе можно выполнить мойку, вычёс и окрас с указанием выходящего веса и стоимости. Пригодный вычёс, разделение и объединение партий будут отдельными документами следующей версии.</p>`;}
function saleTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Покупатель</th><th>Волосы</th><th>Вес</th><th>Продажа</th><th>Оплачено</th>${canFinance()?'<th>Маржа</th><th>Наша доля</th>':''}</tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.customer)}</strong><small>${s.type==='transfer'?'Продажа партнёру':'Конечная продажа'}</small></td><td><button class="tail-link" data-tail="${esc(s.tail)}">${esc(s.tail)}</button><small>${esc(s.lot)}</small></td><td>${fmt(s.weight)} г</td><td>${rub(s.revenue)}</td><td>${rub(s.paid)}<small>${s.paid===s.revenue?'Полная оплата':'Есть задолженность'}</small></td>${canFinance()?`<td class="${s.margin<0?'negative':'positive'}">${rub(s.margin)}</td><td>${s.share?rub(s.share):'—'}</td>`:''}</tr>`).join('')||'<tr><td colspan="8" class="empty">Продаж пока нет</td></tr>'}</tbody></table></div>`;}
function sales(){const rows=state.sales.filter(s=>s.owner===workspace);return head('Продажи без потерянных граммов','Частичные продажи, оплаты и автоматическое списание себестоимости.',canSell()?btn(icon('plus')+' Новая продажа','sell'):'')+panel('Продажи компании',saleTable(rows),'Все продажи в демобазе');}
function partners(){if(workspace!=='main')return head('Расчёты с главной компанией','Доля начисляется с маржи после прямых затрат на волосы.')+partnerPanel(state.partners.find(p=>p.id===workspace));return head('Одна история. Разные компании.','Видите дальнейшее движение ваших волос и свою долю от продаж.')+`<div class="partner-cards">${state.partners.map(partnerPanel).join('')}</div><div class="section-gap">${panel('Продажи партнёров',saleTable(state.sales.filter(s=>s.owner!=='main')),'Только волосы главной компании')}</div>`;}
function partnerPanel(p){const ts=state.tails.filter(t=>t.owner===p.id),ss=state.sales.filter(s=>s.owner===p.id),shares=ss.reduce((a,s)=>a+s.share,0),cost=ts.reduce((a,t)=>a+t.cost,0);return `<section class="panel partner-card"><div class="partner-card-header"><div class="partner-avatar">${esc(p.name[0])}</div><div><h2>${esc(p.name)}</h2><p>${esc(p.city)} · самостоятельный кабинет</p></div><span class="badge purple">${p.share}% / ${100-p.share}%</span></div><div class="partner-stats"><div><label>Остаток ваших волос</label><strong>${kg(ts.reduce((a,t)=>a+t.weight,0))}</strong></div><div><label>Стоимость остатка у партнёра</label><strong>${canFinance()?rub(cost):'Скрыто'}</strong></div><div><label>Выручка конечных продаж</label><strong>${canFinance()?rub(ss.reduce((a,s)=>a+s.revenue,0)):'Скрыто'}</strong></div><div><label>Доля главной компании</label><strong class="positive">${canFinance()?rub(shares):'Скрыто'}</strong></div></div><p class="note">В расчёт входят цена покупки волос и прямые затраты на обработку. Аренда и общие расходы не уменьшают разделяемую маржу.</p><button class="btn secondary" data-workspace="${p.id}">Открыть кабинет ${icon('arrow')}</button></section>`;}
function finances(){if(!canFinance())return head('Финансовые данные скрыты','Выберите роль руководителя или бухгалтера для просмотра демонстрации.')+`<div class="note">В прототипе переключатель ролей показывает будущий интерфейс. Реальная авторизация и серверные права доступа пока не подключены.</div>`;const m=E.metrics(state,workspace);return head('Деньги и прибыль — отдельно','Начисления, оплаты, остатки и партнёрские расчёты.',btn(icon('download')+' Выгрузить CSV','export',true))+`<div class="metrics">${metric('Выручка',rub(m.revenue),'Проведённые продажи','sales')}${metric('Получено денег',rub(m.paid),'Оплаты по продажам','finances')}${metric('Долг покупателей',rub(m.debt),'Включая покупку волос партнёрами','partners')}${metric('Маржа с долей',rub(m.margin),'До общих расходов','finances',true)}</div>`+panel('Экономика поставок',`<div class="table-wrap"><table><thead><tr><th>Поставка</th><th>Закупка с расходами</th><th>Выручка компании</th><th>Начисленная маржа</th><th>Остаток компании</th></tr></thead><tbody>${state.purchases.filter(p=>workspace==='main'||state.tails.some(t=>t.lot===p.id&&t.owner===workspace)).map(p=>{const ss=state.sales.filter(s=>s.lot===p.id&&s.owner===workspace),ts=state.tails.filter(t=>t.lot===p.id&&t.owner===workspace),share=workspace==='main'?state.sales.filter(s=>s.lot===p.id).reduce((a,s)=>a+s.share,0):0;return `<tr><td><strong>${esc(p.id)}</strong><small>${esc(p.supplier)}</small></td><td>${workspace==='main'?rub(p.cost):'Скрыто'}</td><td>${rub(ss.reduce((a,s)=>a+s.revenue,0))}</td><td>${rub(ss.reduce((a,s)=>a+s.margin-s.share,0)+share)}</td><td>${rub(ts.reduce((a,t)=>a+t.cost,0))}</td></tr>`;}).join('')}</tbody></table></div>`,'Текущий результат · непроданные волосы остаются в запасе')+`<p class="note">В этой версии показан управленческий результат до общих расходов. Оплаты закупок, партнёрские выплаты, курсовые разницы и полноценное движение по счетам ещё не реализованы.</p>`;}
function graph(){return head('Происхождение видно на каждом шаге','Выберите хвост и проследите путь от поставщика до продажи.')+`<div class="graph-grid">${wsTails().map(t=>`<button class="graph-node" data-tail="${esc(t.id)}"><span class="badge">${esc(t.lot)}</span><strong>${esc(lotName(t))} → ${esc(t.id)}</strong><small>${t.history.length} событий · ${fmt(t.weight)} г осталось</small><small>${esc(t.location)}</small></button>`).join('')}</div><p class="note">Нажмите на карточку, чтобы открыть цепочку операций. Разветвлённый граф разделения и объединения волос предусмотрен в ТЗ и будет добавлен вместе с этими операциями.</p>`;}
function assistant(){return head('Спросите у своей компании','Быстрый поиск по данным прототипа. Telegram и голос ещё не подключены.','','Помощник по учёту')+`<div class="assistant panel"><div class="assistant-welcome"><div class="brandmark">${icon('assistant')}</div><h2>Что хотите узнать?</h2><p class="subtitle">Расчёт из текущих данных вашего рабочего пространства</p><div class="suggestions">${['Сколько заработали?','Где H-001?','Сколько волос осталось?','Кто поставщики?','Выгрузи финансовые результаты'].map(s=>`<button data-prompt="${esc(s)}">${s}</button>`).join('')}</div></div><div id="messages" class="messages"></div><form id="chat-form" class="chat-form"><input name="request" placeholder="Например: сколько заработали?" required aria-label="Запрос помощнику"><button class="btn" type="submit">${icon('arrow')}</button></form></div>`;}
function roles(){const names=['Руководитель','Закупщик','Производство','Склад','Продавец','Бухгалтер','Партнёр'];const rows=[['Приёмка и закупочные цены',[1,1,0,0,0,1,0]],['Обработка и потери',[1,0,1,0,0,0,1]],['Перемещения',[1,0,0,1,0,0,1]],['Продажи',[1,0,0,0,1,1,1]],['Себестоимость и маржа',[1,0,0,0,0,1,1]],['Финансовые выгрузки',[1,0,0,0,0,1,1]]];return head('Каждый видит свою часть','Пример распределения прав. Текущая роль: '+esc(role))+panel('Матрица ролей',`<div class="table-wrap"><table class="permissions"><thead><tr><th>Действие</th>${names.map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${rows.map(([n,flags])=>`<tr><td>${n}</td>${flags.map(f=>`<td class="${f?'allowed':'denied'}">${f?'✓':'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)+`<p class="note">Переключение роли в верхней панели — демонстрация интерфейса, а не защита данных. В рабочей системе нужны отдельные учётные записи и серверная проверка прав.</p>`;}
function settings(){return head('Правила вашей экономики','Предварительные значения из ТЗ. Исторические операции сохраняют свои условия.')+`<form id="settings-form"><div class="settings-grid"><div class="panel setting-card"><label for="rate">Курс для новых закупок · ₽ за USD</label><input id="rate" name="rate" type="number" min="0.01" step="0.01" value="${state.settings.rate}" required></div><div class="panel setting-card"><label for="tariff">Обработка · ₽ за кг входа</label><input id="tariff" name="tariff" type="number" min="0" step="1" value="${state.settings.tariff}" required></div><div class="panel setting-card"><label for="share">Доля для новых соглашений · %</label><input id="share" name="share" type="number" min="0" max="100" step="1" value="${state.settings.share}" required></div></div><div class="actions section-gap"><button class="btn" type="submit">Сохранить настройки</button><button class="btn secondary" type="button" data-action="reset">Восстановить демоданные</button></div></form><p class="note">Изменения хранятся в этом браузере. Доля существующего партнёра задаётся в карточке соглашения и не изменяется общим значением. Облачная синхронизация пока не подключена.</p>`;}
const views={overview,inventory,purchases,production,sales,partners,finances,graph,assistant,roles,settings};
function render(){const navigation=Object.keys(labels).map(k=>`${k==='graph'?'<div class="nav-label">Контроль и аналитика</div>':''}<button class="nav-btn ${k===view?'active':''}" data-view="${k}">${icon(k)}${labels[k]}${k==='inventory'?`<span class="count">${available().length}</span>`:''}</button>`).join('');$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brandmark">h</span><div>hairflow<small>FROM ROOT TO RESULT</small></div></div><div class="nav-label">Рабочее пространство</div><nav>${navigation}</nav><div class="sidebar-bottom"><div class="workspace"><strong>${wsName()}</strong><select id="workspace" aria-label="Рабочее пространство"><option value="main">Главная компания</option>${state.partners.map(p=>`<option value="${p.id}" ${workspace===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="sidebar-user"><div class="avatar">А</div><div><strong>Алексей</strong><span>Демонстрация интерфейса</span></div></div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" aria-label="Открыть меню" data-action="menu">${icon('menu')}</button><div class="breadcrumb"><span>${wsName()}</span><span>/</span><strong>${labels[view]}</strong></div><div class="top-actions"><div class="search-box"><input id="global-search" placeholder="Найти хвост по номеру" aria-label="Поиск хвоста"></div><span class="version">Прототип v0.1</span><select class="role-select" id="role" aria-label="Демонстрационная роль">${['Руководитель','Закупщик','Производство','Склад','Продавец','Бухгалтер','Партнёр'].map(r=>`<option ${role===r?'selected':''}>${r}</option>`).join('')}</select></div></header><div class="content"><div class="demo-note"><span class="dot"></span>Демоданные · изменения сохраняются в этом браузере · роли показывают будущий интерфейс</div>${views[view]()}</div></main></div>`;}
function openModal(title,body,wide=false){$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${title}</h2><button class="close" data-action="close" aria-label="Закрыть">×</button></div>${body}</section></div>`;const f=$('#modal-root input');if(f)f.focus();}
function close(){modal=null;$('#modal-root').innerHTML='';}
const field=(label,name,type='text',value='',extra='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const selectField=(label,name,options)=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options}</select></div>`;
function formShell(body,kind){return `<form id="operation-form" data-kind="${kind}"><div class="form-grid">${body}</div><div class="form-preview"><span id="preview-label">Автоматический расчёт</span><strong id="form-result">—</strong></div><div class="form-error" id="form-error" role="alert"></div><div class="modal-actions"><button class="btn secondary" type="button" data-action="close">Отмена</button><button class="btn" type="submit">Провести операцию</button></div></form>`;}
function openOperation(kind,tailId){const permissions={purchase:canPurchase,process:canProcess,move:canMove,sell:canSell};if(!permissions[kind]())return toast('Операция недоступна для выбранной роли');let ts=available().filter(t=>t.owner===workspace);if(kind==='purchase'&&workspace!=='main')return toast('Закупка в этом прототипе создаётся в главной компании');if(kind!=='purchase'&&!ts.length)return toast('В этой компании нет доступных волос');modal={kind,tailId:tailId||ts[0]?.id};const opts=ts.map(t=>`<option value="${esc(t.id)}" ${t.id===modal.tailId?'selected':''}>${esc(t.id)} · ${fmt(t.weight)} г · ${esc(t.color)}</option>`).join('');let b='';
 if(kind==='purchase')b=field('Поставщик','supplier','text','','required')+field('Деревня','village','text','','required')+field('Вес сырья · г','weight','number',1000,'min="1" step="0.1" required')+field('Цена за кг · USD','price','number',200,'min="0.01" step="0.01" required')+field('Курс · ₽ за USD','rate','number',state.settings.rate,'min="0.01" step="0.01" required')+field('Расходы поставки · ₽','expenses','number',1800,'min="0" step="0.01" required')+field('Длина · см','length','number',60,'min="1" max="200" required')+selectField('Качество','quality','<option>Стандарт</option><option>Премиум</option>');
 else{b=selectField('Волосы','tail',opts);if(kind==='process'){b+=selectField('Операция','operation','<option>Окрас</option><option>Мойка</option><option>Вычёс</option>')+field('Выходящий вес · г','output','number',E.tail(state,modal.tailId).weight,'min="0.1" step="0.1" required')+field('Стоимость операции · ₽','fee','number',E.money(E.tail(state,modal.tailId).weight/1000*state.settings.tariff),'min="0" step="0.01" required')+field('Итоговый цвет','color','text',E.tail(state,modal.tailId).color);}
 if(kind==='move'){b+=selectField('Куда передать','target','<option>Магазин</option><option>Производство</option><option>Склад сырья</option>'+(workspace==='main'?state.partners.map(p=>`<option value="${p.id}">${esc(p.name)} · продажа партнёру</option>`).join(''):''))+field('Цена продажи партнёру · ₽','price','number',E.money(E.tail(state,modal.tailId).cost*1.15),'min="0.01" step="0.01"')+`<div class="field full"><p class="text-muted">При внутреннем перемещении цена не используется. Продажа партнёру создаёт его входящий остаток и задолженность.</p></div>`;}
 if(kind==='sell')b+=field('Покупатель','customer','text','','required')+field('Вес продажи · г','weight','number',Math.min(200,E.tail(state,modal.tailId).weight),'min="0.1" step="0.1" required')+field('Сумма продажи · ₽','revenue','number',15000,'min="0" step="0.01" required')+field('Получено оплаты · ₽','paid','number',0,'min="0" step="0.01" required');}
 openModal({purchase:'Новая поставка сырья',process:'Обработка волос',move:'Перемещение или передача',sell:'Новая продажа'}[kind],formShell(b,kind));updatePreview();}
function updatePreview(){const f=$('#operation-form');if(!f)return;const d=Object.fromEntries(new FormData(f)),kind=f.dataset.kind;try{let result='',label='';if(kind==='purchase'){result=rub(Number(d.weight)/1000*Number(d.price)*Number(d.rate)+Number(d.expenses));label='Себестоимость поставки';}else{const t=E.tail(state,d.tail);if(kind==='process'){result=rub((t.cost+Number(d.fee))/Number(d.output)*1000)+' / кг';label='Новая себестоимость · потери '+fmt(t.weight-Number(d.output))+' г';}if(kind==='sell'){const cost=t.cost*Number(d.weight)/t.weight,margin=Number(d.revenue)-cost;result=rub(margin);label='Маржа'+(t.owner==='main'?'':' · доля главной компании '+rub(margin*(t.share||0)/100));}if(kind==='move'){result=state.partners.some(p=>p.id===d.target)?rub(Number(d.price)-t.cost):'Без изменения стоимости';label=state.partners.some(p=>p.id===d.target)?'Ваша маржа при передаче':'Внутреннее перемещение';}}$('#form-result').textContent=result;$('#preview-label').textContent=label;}catch{}}
const code128Patterns=['212222','222122','222221','121223','121322','131222','122213','122312','132212','221213','221312','231212','112232','122132','122231','113222','123122','123221','223211','221132','221231','213212','223112','312131','311222','321122','321221','312212','322112','322211','212123','212321','232121','111323','131123','131321','112313','132113','132311','211313','231113','231311','112133','112331','132131','113123','113321','133121','313121','211331','231131','213113','213311','213131','311123','311321','331121','312113','312311','332111','314111','221411','431111','111224','111422','121124','121421','141122','141221','112214','112412','122114','122411','142112','142211','241211','221114','413111','241112','134111','111242','121142','121241','114212','124112','124211','411212','421112','421211','212141','214121','412121','111143','111341','131141','114113','114311','411113','411311','113141','114131','311141','411131','211412','211214','211232','2331112'];
function barcode(text){const values=[104,...Array.from(text,c=>c.charCodeAt(0)-32)];let sum=104;values.slice(1).forEach((v,i)=>sum+=v*(i+1));values.push(sum%103,106);let x=10,rects='';for(const v of values){const pattern=code128Patterns[v];if(!pattern)return '';Array.from(pattern).forEach((w,i)=>{w=Number(w);if(i%2===0)rects+=`<rect x="${x}" y="0" width="${w}" height="50"/>`;x+=w;});}return `<svg viewBox="0 0 ${x+10} 50" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Штрихкод ${esc(text)}" preserveAspectRatio="none">${rects}</svg>`;}
function tailDetails(id){let t;try{t=E.tail(state,id);}catch{return toast('Хвост не найден');}if(workspace!=='main'&&t.owner!==workspace)return toast('Этот хвост находится в другой компании');modal={kind:'details',tailId:id};const p=state.purchases.find(p=>p.id===t.lot);const label=`<div class="barcode-label">${barcode(t.id)}<strong>${esc(t.id)}</strong><p>${t.length} см · ${esc(t.color)} · ${fmt(t.weight)} г<br>${esc(t.quality)} · ${esc(t.lot)}</p></div>`;openModal('Карточка '+esc(t.id),`<div class="details-grid"><div><span class="badge green">${esc(t.location)}</span><div class="detail-kv"><div><label>Остаток</label><strong>${fmt(t.weight)} г</strong></div><div><label>Длина</label><strong>${t.length} см</strong></div><div><label>Цвет</label><strong>${esc(t.color)}</strong></div><div><label>Качество</label><strong>${esc(t.quality)}</strong></div><div><label>Поставка</label><strong>${esc(t.lot)}</strong></div><div><label>Поставщик</label><strong>${esc(p?.supplier)}</strong></div>${canFinance()?`<div><label>Себестоимость остатка</label><strong>${rub(t.cost)}</strong></div><div><label>Цена за кг</label><strong>${t.weight?rub(t.cost/t.weight*1000):'—'}</strong></div>`:''}<div><label>Потери обработки</label><strong>${fmt(t.loss)} г</strong></div><div><label>Состояние</label><strong>${esc(t.stage)}</strong></div></div>${label}<div class="actions section-gap"><button class="btn secondary" data-action="print">Печать этикетки</button>${t.owner===workspace&&t.weight>0&&canSell()?`<button class="btn" data-operation="sell" data-id="${esc(t.id)}">Продать</button>`:''}</div></div><div><h2>Путь волос</h2><div class="history">${t.history.map((h,i)=>`<div class="history-item"><span class="history-mark"></span><div><strong>${esc(h.name)}</strong><small>${fmt(h.weight)} г · ${new Date(h.date).toLocaleDateString('ru-RU')}${canFinance()&&h.cost!==undefined?' · '+rub(h.cost):''}</small></div></div>`).join('')}</div>${t.owner===workspace&&t.weight>0?`<div class="actions">${canProcess()?`<button class="btn secondary" data-operation="process" data-id="${esc(t.id)}">Обработать</button>`:''}${canMove()?`<button class="btn secondary" data-operation="move" data-id="${esc(t.id)}">Переместить</button>`:''}</div>`:''}<p class="note">Операции сохраняют связь с исходной поставкой. Веса и себестоимость обновляются автоматически.</p></div></div>`,true);}
function exportCSV(){const rows=canFinance()?state.sales.filter(s=>s.owner===workspace).map(s=>({Поставка:s.lot,Хвост:s.tail,Покупатель:s.customer,Вес:s.weight,Продажа:s.revenue,Себестоимость:s.cost,Маржа:s.margin,Доля:s.share,Оплачено:s.paid})):available().map(t=>({Хвост:t.id,Поставка:t.lot,Вес:t.weight,Длина:t.length,Цвет:t.color,Качество:t.quality,Место:t.location}));if(!rows.length)return toast('Нет данных для выгрузки');const val=x=>'"'+String(x).replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"';const text='\ufeff'+[Object.keys(rows[0]).map(val).join(';'),...rows.map(r=>Object.values(r).map(val).join(';'))].join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='hairflow-'+workspace+'-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Выгрузка подготовлена');}
function ask(text){const box=$('#messages');if(!box)return;box.insertAdjacentHTML('beforeend',`<div class="message user">${esc(text)}</div>`);const q=text.toLowerCase(),m=E.metrics(state,workspace);let answer='';const id=text.match(/H-[\w-]+/i)?.[0].toUpperCase();if(id){const t=wsTails().find(t=>t.id.toUpperCase()===id);answer=t?`${t.id}: ${t.location}.\nОстаток ${fmt(t.weight)} г, ${t.length} см, ${t.color}.\nПоставка ${t.lot}, поставщик ${lotName(t)}.\nОткройте карточку через раздел «Волосы и остатки».`:'Этот номер не найден в текущем рабочем пространстве.';}else if(/выгруз/.test(q)){exportCSV();answer='Подготовлена CSV-выгрузка разрешённых данных текущего кабинета.';}else if(/заработ|прибыл|марж|финанс/.test(q)){answer=canFinance()?`Маржа компании: ${rub(m.margin)}.\nВыручка: ${rub(m.revenue)}. Получено оплат: ${rub(m.paid)}.\nДоля от партнёров: ${rub(m.shares)}.\nВсе операции демобазы. Общие расходы ещё не учтены.`:'Финансовые данные недоступны для выбранной демонстрационной роли.';}else if(/поставщик/.test(q)){answer=[...new Set(state.purchases.filter(p=>workspace==='main'||wsTails().some(t=>t.lot===p.id)).map(p=>p.supplier))].join(', ')+'.\nДля объективной оценки качества пока недостаточно данных. Можно сравнить поставки и потери обработки.';}else if(/остал|остат|волос/.test(q)){answer=`В текущей компании осталось ${kg(m.weight)} волос.\n${workspace==='main'?'Остатки партнёров показаны отдельно в разделе «Партнёры».':''}`;}else answer='В прототипе доступны запросы об остатках, марже, поставщиках, местонахождении хвоста по номеру и CSV-выгрузке. Попробуйте один из примеров выше.';box.insertAdjacentHTML('beforeend',`<div class="message">${esc(answer)}</div>`);box.scrollIntoView({behavior:'smooth',block:'end'});}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el){if(e.target.classList.contains('modal-overlay'))close();return;}if(el.dataset.view){view=el.dataset.view;query='';render();return;}if(el.dataset.tail){tailDetails(el.dataset.tail);return;}if(el.dataset.workspace){workspace=el.dataset.workspace;role='Партнёр';view='overview';render();return;}if(el.dataset.operation){openOperation(el.dataset.operation,el.dataset.id);return;}if(el.dataset.prompt){ask(el.dataset.prompt);return;}const action=el.dataset.action;if(['purchase','process','sell','move'].includes(action))openOperation(action);if(action==='close')close();if(action==='menu')$('.sidebar').classList.toggle('open');if(action==='export')exportCSV();if(action==='print'){const t=E.tail(state,modal.tailId);document.querySelector('.print-area')?.remove();const area=document.createElement('div');area.className='print-area';area.innerHTML=`<div class="barcode-label">${barcode(t.id)}<strong>${esc(t.id)}</strong><p>${t.length} см · ${esc(t.color)} · ${fmt(t.weight)} г<br>${esc(t.lot)}</p></div>`;document.body.append(area);window.print();}if(action==='reset'){openModal('Восстановить демоданные','<p class="subtitle">Созданные вами поставки и операции в этом браузере будут заменены исходными примерами.</p><div class="modal-actions"><button class="btn secondary" data-action="close">Отмена</button><button class="btn danger" data-action="confirm-reset">Восстановить</button></div>');}if(action==='confirm-reset'){state=E.seed();save();close();render();toast('Демоданные восстановлены');}});
document.addEventListener('change',e=>{if(e.target.id==='workspace'){workspace=e.target.value;role=workspace==='main'?'Руководитель':'Партнёр';render();}if(e.target.id==='role'){role=e.target.value;render();}if(e.target.id==='stage-filter'){stageFilter=e.target.value;render();}if(e.target.id==='f-tail'&&modal?.kind==='process'){const t=E.tail(state,e.target.value);$('#f-output').value=t.weight;$('#f-fee').value=E.money(t.weight/1000*state.settings.tariff);$('#f-color').value=t.color;}updatePreview();});
document.addEventListener('input',e=>{if(e.target.id==='inventory-search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#inventory-search').focus();$('#inventory-search').setSelectionRange(pos,pos);}if(e.target.closest('#operation-form'))updatePreview();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Enter'&&e.target.id==='global-search'){const t=wsTails().find(t=>t.id.toLowerCase()===e.target.value.trim().toLowerCase());if(t)tailDetails(t.id);else toast('Хвост с таким номером не найден');}});
document.addEventListener('submit',e=>{if(e.target.id==='operation-form'){e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));try{const draft=E.copy(state);if(f.dataset.kind==='purchase')E.purchase(draft,d);if(f.dataset.kind==='process')E.process(draft,d.tail,d);if(f.dataset.kind==='move')E.move(draft,d.tail,d);if(f.dataset.kind==='sell')E.sell(draft,d.tail,d);state=draft;save();close();render();toast('Операция проведена');}catch(err){$('#form-error').textContent=err.message;}}if(e.target.id==='settings-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));state.settings={rate:Number(d.rate),tariff:Number(d.tariff),share:Number(d.share)};save();toast('Настройки сохранены');}if(e.target.id==='chat-form'){e.preventDefault();const t=new FormData(e.target).get('request');ask(t);e.target.reset();}});
render();
